tape( 'the function computes row and column scale factors (row-major)', function test( t ) {
	var data;
	var info;
	var out;
	var A;
	var R;
	var C;

	data = ROW_MAJOR_3X3;

	A = new Float64Array( data.A );
	R = new Float64Array( data.R );
	C = new Float64Array( data.C );
	out = new Float64Array( data.out );

	info = dgeequ( data.order, data.M, data.N, A, data.LDA, R, C, out );

	t.strictEqual( info, data.info, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( R, new Float64Array( data.R_expected ) ), true, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( C, new Float64Array( data.C_expected ) ), true, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, new Float64Array( data.out_expected ) ), true, 'returns expected value' );

	t.end();
});

