tape( 'the function clamps row and column maxima which underflow to the smallest normal number', function test( t ) {
	var data;
	var info;
	var out;
	var A;
	var R;
	var C;

	data = ROW_MAJOR_UNDERFLOW;

	A = new Float64Array( data.A );
	R = new Float64Array( data.R );
	C = new Float64Array( data.C );
	out = new Float64Array( data.out );

	info = dgeequ( data.order, data.M, data.N, A, data.LDA, R, C, out );

	// Every row maximum is subnormal, and thus every scale factor should saturate at `1/smallest normal` (rather than overflow to infinity)...
	t.strictEqual( info, data.info, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( R, new Float64Array( data.R_expected ) ), true, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( C, new Float64Array( data.C_expected ) ), true, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, new Float64Array( data.out_expected ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function clamps row and column maxima which exceed the reciprocal of the smallest normal number', function test( t ) {
	var data;
	var info;
	var out;
	var A;
	var R;
	var C;

	data = ROW_MAJOR_OVERFLOW;

	A = new Float64Array( data.A );
	R = new Float64Array( data.R );
	C = new Float64Array( data.C );
	out = new Float64Array( data.out );

	info = dgeequ( data.order, data.M, data.N, A, data.LDA, R, C, out );

	// Every row maximum exceeds `1/smallest normal`, and thus the smallest and largest row maxima should both saturate, yielding a ratio of exactly one...
	t.strictEqual( info, data.info, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( R, new Float64Array( data.R_expected ) ), true, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( C, new Float64Array( data.C_expected ) ), true, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, new Float64Array( data.out_expected ) ), true, 'returns expected value' );

	t.end();
});

