tape( 'the function supports 1x1 matrices', function test( t ) {
	var info;
	var out;
	var A;
	var R;
	var C;

	A = new Float64Array( [ 5.0 ] );
	R = new Float64Array( 1 );
	C = new Float64Array( 1 );
	out = new Float64Array( 3 );

	info = dgeequ( 'row-major', 1, 1, A, 1, R, C, out );

	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( R, new Float64Array( [ 0.2 ] ) ), true, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( C, new Float64Array( [ 1.0 ] ) ), true, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, new Float64Array( [ 1.0, 1.0, 5.0 ] ) ), true, 'returns expected value' );

	A = new Float64Array( [ 0.0 ] );
	R = new Float64Array( 1 );
	C = new Float64Array( 1 );
	out = new Float64Array( [ -1.0, -1.0, -1.0 ] );

	info = dgeequ( 'column-major', 1, 1, A, 1, R, C, out );

	// Only `AMAX` should be set, as the routine exits before computing the scale factors...
	t.strictEqual( info, 1, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, new Float64Array( [ -1.0, -1.0, 0.0 ] ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns early if M = 0 or N = 0', function test( t ) {
	var expected;
	var info;
	var out;
	var A;
	var R;
	var C;

	A = new Float64Array( 0 );
	R = new Float64Array( 0 );
	C = new Float64Array( 0 );
	expected = new Float64Array( [ 1.0, 1.0, 0.0 ] );

	out = new Float64Array( 3 );
	info = dgeequ( 'row-major', 0, 0, A, 1, R, C, out );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 3 );
	info = dgeequ( 'row-major', 0, 3, A, 3, R, C, out );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	out = new Float64Array( 3 );
	info = dgeequ( 'row-major', 3, 0, A, 1, R, C, out );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( out, expected ), true, 'returns expected value' );

	t.end();
});
